  q(636,"recall","Nerve thickening is also seen in:","Leprosy and charcot marie tooth disease","Diabetes and uremia","Lead and dapsone","GBS and AIDP",exp="Nerve thickening also seen in : leprosy; charcot marie tooth disease"),
  q(636,"recall","The characteristic feature of POEMS syndrome includes:","Increased VEGF","Decreased VEGF","Normal VEGF with ↑ IL-6 only","Increased EPO",exp="POEMS characteristic feature: increased VEGF"),
  q(636,"recall","The myeloma type in POEMS syndrome is:","λ light chain myeloma","κ light chain myeloma","IgM myeloma","Non-secretory myeloma",exp="POEMS: λ light chain myeloma"),
