  q(640,"recall","Ptosis + ophthalmoplegia without dysarthria indicates:","CPEO (chronic progressive external ophthalmoplegia)","Oculo-pharyngeal muscle dystrophy","Myotonic dystrophy","FSHD",exp="Ptosis + ophthalmoplegia with - dysarthria : CPEO (Chronic progressive external ophthalmoplegia)"),
