  q(640,"recall","Muscular diseases with muscle pain listed are:","Mitochondrial myopathy, inflammatory muscle disease (30%), rhabdomyolysis","Duchenne and Becker","Congenital myopathies","Channelopathies only",exp="Muscular diseases with muscle pain: mitochondrial myopathy; inflammatory muscle disease (30%); rhabdomyolysis"),
