  q(641,"recall","Causes of cramps listed are:","Dehydration, hyponatremia, amyotrophic lateral sclerosis (ALS), Duchenne muscular dystrophy","Emery-Dreifuss muscular dystrophy, mitochondrial myopathy","Hypernatremia, hyperkalemia","Myotonic dystrophy, paramyotonia",exp="Cramps causes: dehydration; hyponatremia; ALS; Duchenne muscular dystrophy"),
  q(641,"recall","Causes of contractures listed are:","Emery-Dreifuss muscular dystrophy and mitochondrial myopathy","Dehydration and hyponatremia","ALS and Duchenne","Hyperkalemic periodic paralysis",exp="Contractures causes: Emery-Dreifuss muscular dystrophy; mitochondrial myopathy"),
  q(641,"recall","Other symptoms listed in ALS are:","Cramps, atrophy, fasciculations, wasting","Contractures, pain, cramps, weakness with exercise","Myotonia and cataract","Ptosis and dysphagia",exp="Other symptoms in ALS: cramps; atrophy; fasciculations; wasting"),
  q(641,"recall","Other symptoms in mitochondrial myopathies are:","Contractures, pain, cramps, weakness associated with exercise","Cramps, atrophy, fasciculations, wasting","Myalgia with trigger points","Fluctuating diurnal weakness",exp="Other symptoms in mitochondrial myopathies: contractures; pain; cramps; weakness - associated with exercise"),
